element.style.display = 'inline-flex';
element.style.alignItems = 'center';
element.style.justifyContent = 'center';
element.style.padding = '6px 14px';
element.style.margin = '0 4px';
element.style.borderRadius = '4px';
element.style.backgroundColor = '#3366cc';
element.style.color = '#ffffff';
element.style.fontWeight = 'bold';
element.style.textDecoration = 'none';
element.style.border = '1px solid #2a4b8d';
element.style.boxShadow = '0 1px 3px rgba(0,0,0,0.15)';
element.style.transition = 'background-color 0.15s ease';
element.style.cursor = 'pointer';

const originalMouseOver = function() {
    element.style.backgroundColor = '#2a4b8d';
};
const originalMouseOut = function() {
    element.style.backgroundColor = '#3366cc';
};

element.addEventListener('mouseover', originalMouseOver);
element.addEventListener('mouseout', originalMouseOut);
